// glyph-rain — matrix-style glyph rain that reveals an image.
import createPost from './post.js';

const CHARSET = 'アィウエオカキクケコサシスセソタチツテトナニヌネノ01<>/{}[]=+*#$';
const DIRECTIONS = ['down', 'up', 'vertical', 'right', 'left', 'horizontal'];
const MASK_ALPHA = 60; // image pixels under this alpha are not part of the glyph
const RAMP = 16; // trail colour steps, precomputed once per config

export const DEFAULTS = {
    container: null, // where to append the canvas (default: document.body)
    canvas: null, // use an existing canvas instead, styled by you
    autoStart: true,
    cellSize: 18, // px per grid cell, also the glyph size
    fps: 30, // the whole frame is redrawn, so this is the main cost knob
    fontFamily: 'monospace',
    charset: CHARSET,
    glyph: {
        src: null, // image url, data uri, HTMLImageElement or canvas
        scale: 0.6, // fraction of the screen's short side
    },
    animation: {
        churn: { value: 4, random: 0.5 }, // symbol changes per second, max 10
        length: { value: 0.5, random: 0.4 }, // trail length in screens, max 3
        speed: { value: 20, random: 0.5 }, // symbols per second, screen agnostic
        gap: { value: 1.2, random: 0.5 }, // screens between drops of one lane
        direction: 'down',
    },
    color: {
        from: '#00aaff',
        to: '#b3e5ff',
        brightness: 1,
        rainOpacity: 0.7, // drops falling outside the glyph
        glyphOpacity: 1, // the glyph itself and the drops crossing it
    },
    blur: 0, // px
    chromaticAberration: 0, // px of rgb split
    filmGrain: 0, // 0..1
    bloom: { radius: 8, intensity: 0, threshold: 0.6 },
    hdrBloom: { iterations: 4, intensity: 0, scatter: 0.7, threshold: 0.8 },
    onIdle: null, // fired once the last drop is gone after stop()
};

const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);
const num = (v, d) => (typeof v === 'number' && isFinite(v) ? v : d);
const jitter = (v, r) => v * (1 + (Math.random() * 2 - 1) * r);

const merge = (a, b) => {
    const out = { ...a };
    for (const k in b) {
        const v = b[k];
        out[k] =
            v && typeof v === 'object' && !Array.isArray(v) &&
            a[k] && typeof a[k] === 'object'
                ? merge(a[k], v)
                : v;
    }
    return out;
};

// Accepts either `4` or `{ value: 4, random: 0.5 }`.
const param = (v, def, lo, hi) => {
    const p = typeof v === 'number' ? { value: v } : v || {};
    return {
        value: clamp(num(p.value, def.value), lo, hi),
        random: clamp(num(p.random, def.random), 0, 1),
    };
};

export const resolveOptions = (raw = {}) => {
    const o = merge(DEFAULTS, raw);
    const a = o.animation;
    o.cellSize = clamp(num(o.cellSize, 18), 4, 200);
    o.fps = clamp(num(o.fps, 30), 1, 120);
    o.glyph.scale = clamp(num(o.glyph.scale, 0.6), 0, 1);
    a.churn = param(a.churn, DEFAULTS.animation.churn, 0, 10);
    a.length = param(a.length, DEFAULTS.animation.length, 0.01, 3);
    a.speed = param(a.speed, DEFAULTS.animation.speed, 0.1, 200);
    a.gap = param(a.gap, DEFAULTS.animation.gap, 0.05, 5);
    if (!DIRECTIONS.includes(a.direction)) a.direction = 'down';
    o.color.brightness = clamp(num(o.color.brightness, 1), 0, 4);
    o.color.rainOpacity = clamp(num(o.color.rainOpacity, 0.7), 0, 1);
    o.color.glyphOpacity = clamp(num(o.color.glyphOpacity, 1), 0, 1);
    o.blur = clamp(num(o.blur, 0), 0, 100);
    o.chromaticAberration = clamp(num(o.chromaticAberration, 0), 0, 50);
    o.filmGrain = clamp(num(o.filmGrain, 0), 0, 1);
    o.bloom = {
        radius: clamp(num(o.bloom.radius, 8), 0, 128),
        intensity: clamp(num(o.bloom.intensity, 0), 0, 4),
        threshold: clamp(num(o.bloom.threshold, 0.6), 0, 1),
    };
    o.hdrBloom = {
        iterations: Math.round(clamp(num(o.hdrBloom.iterations, 4), 1, 8)),
        intensity: clamp(num(o.hdrBloom.intensity, 0), 0, 4),
        scatter: clamp(num(o.hdrBloom.scatter, 0.7), 0, 1),
        threshold: clamp(num(o.hdrBloom.threshold, 0.8), 0, 1),
    };
    return o;
};

// Distance travelled along a lane, so both directions share the same maths.
// It is its own inverse: signed(signed(p)) === p.
export const signed = (p, sign, span) => (sign > 0 ? p : span - 1 - p);

// Any css colour, resolved by the browser instead of by a parser of our own.
const parseColor = (() => {
    let ctx;
    return (c) => {
        if (!ctx) ctx = document.createElement('canvas').getContext('2d');
        ctx.fillStyle = '#000000';
        ctx.fillStyle = c;
        const s = ctx.fillStyle;
        if (s[0] === '#')
            return [1, 3, 5].map((i) => parseInt(s.slice(i, i + 2), 16));
        return (s.match(/[\d.]+/g) || [0, 0, 0]).slice(0, 3).map(Number);
    };
})();

export default class GlyphRain {
    constructor(options = {}) {
        this.raw = options;
        this.opts = resolveOptions(options);
        const o = this.opts;

        this.canvas = o.canvas || document.createElement('canvas');
        this.owned = !o.canvas;
        if (this.owned) {
            Object.assign(this.canvas.style, {
                // inside a container it fills that box, on its own the viewport
                position: o.container ? 'absolute' : 'fixed',
                inset: '0',
                pointerEvents: 'none',
            });
            (o.container || document.body).appendChild(this.canvas);
        }
        // A canvas is a replaced element: with no css size it lays out at its
        // attribute size (300x150) however it is positioned, and we measure it
        // to pick the resolution. Filling its box is the only sane default.
        Object.assign(this.canvas.style, { width: '100%', height: '100%' });
        this.ctx = this.canvas.getContext('2d');
        this.scene = document.createElement('canvas');
        this.sctx = this.scene.getContext('2d');
        this.layer = document.createElement('canvas'); // rasterised glyph image
        this.lctx = this.layer.getContext('2d');
        this.post = createPost();

        this.lanes = [];
        this.mask = null;
        this.running = false;
        this.started = false;
        this.last = 0;
        this.raf = 0;
        this.image = null;
        this.frame = this.frame.bind(this);

        this.applyColors();
        this.loadImage();
        this.resize();
        this.observer = new ResizeObserver(() => this.resize());
        this.observer.observe(this.canvas);
        if (o.autoStart) this.start();
    }

    // --- config -----------------------------------------------------------

    update(patch = {}) {
        this.raw = merge(this.raw, patch);
        const before = this.opts;
        this.opts = resolveOptions(this.raw);
        this.applyColors();
        if (this.opts.glyph.src !== before.glyph.src) this.loadImage();
        this.resize(true);
    }

    applyColors() {
        const { from, to, brightness } = this.opts.color;
        const a = parseColor(from);
        const b = parseColor(to);
        const css = (c) =>
            `rgb(${c.map((v) => clamp(Math.round(v * brightness), 0, 255)).join(',')})`;
        this.ramp = Array.from({ length: RAMP }, (_, i) => {
            const t = i / (RAMP - 1);
            return css(b.map((v, k) => v + (a[k] - v) * t));
        });
        this.hot = css(b);
        this.dim = css(a);
    }

    loadImage() {
        const src = this.opts.glyph.src;
        this.image = null;
        if (!src) return this.buildMask();
        if (typeof src !== 'string') {
            this.image = src;
            return this.buildMask();
        }
        const img = new Image();
        img.crossOrigin = 'anonymous';
        img.onload = () => {
            this.image = img;
            this.buildMask();
        };
        img.src = src;
    }

    // --- grid -------------------------------------------------------------

    get horizontal() {
        const d = this.opts.animation.direction;
        return d === 'left' || d === 'right' || d === 'horizontal';
    }

    index(lane, pos) {
        return this.horizontal ? lane * this.cols + pos : pos * this.cols + lane;
    }

    cellRect(lane, from, to) {
        const c = this.cell;
        return this.horizontal
            ? [from * c, lane * c, (to - from + 1) * c, c]
            : [lane * c, from * c, c, (to - from + 1) * c];
    }

    laneSign() {
        const d = this.opts.animation.direction;
        if (d === 'vertical' || d === 'horizontal')
            return Math.random() < 0.5 ? 1 : -1;
        return d === 'up' || d === 'left' ? -1 : 1;
    }

    resize(force) {
        const w = Math.max(1, this.canvas.clientWidth || window.innerWidth);
        const h = Math.max(1, this.canvas.clientHeight || window.innerHeight);
        if (!force && this.cols && w === this.canvas.width && h === this.canvas.height)
            return;
        this.canvas.width = this.scene.width = this.layer.width = w;
        this.canvas.height = this.scene.height = this.layer.height = h;

        this.cell = this.opts.cellSize;
        this.cols = Math.ceil(w / this.cell);
        this.rows = Math.ceil(h / this.cell);
        this.span = this.horizontal ? this.cols : this.rows;
        const laneCount = this.horizontal ? this.rows : this.cols;

        const n = this.cols * this.rows;
        this.chars = new Array(n);
        this.churnAt = new Float64Array(n);
        this.churnRate = new Float32Array(n);
        const { value, random } = this.opts.animation.churn;
        for (let i = 0; i < n; i++) {
            this.chars[i] = this.randChar();
            this.churnRate[i] = Math.max(0, jitter(value, random));
            this.churnAt[i] = this.churnRate[i]
                ? performance.now() + (Math.random() * 1000) / this.churnRate[i]
                : Infinity;
        }

        // Lanes that already exist keep their drops, so a resize does not
        // restart the animation. A new direction invalidates them though: their
        // sign and their travel are both tied to the axis they were built on.
        const turned = this.dir !== this.opts.animation.direction;
        this.dir = this.opts.animation.direction;
        const old = turned ? [] : this.lanes;
        this.lanes = Array.from({ length: laneCount }, (_, i) =>
            old[i] || {
                i,
                sign: this.laneSign(),
                drops: [],
                gap: 0, // distance the last drop must cover before the next one
                head: -1,
                tail: -1,
                first: -1,
                last: -1,
            }
        );
        this.buildMask();
    }

    randChar() {
        const s = this.opts.charset;
        return s[(Math.random() * s.length) | 0];
    }

    // Rasterises the image onto the grid: every covered cell becomes a glyph,
    // so drops crossing it reuse that same symbol instead of hiding it.
    buildMask() {
        this.mask = null;
        this.lanes.forEach((l) => {
            l.first = l.last = -1;
        });
        const img = this.image;
        const w = this.canvas.width;
        const h = this.canvas.height;
        this.lctx.clearRect(0, 0, w, h);
        if (!img || !(img.naturalWidth || img.width)) return;

        const iw = img.naturalWidth || img.width;
        const ih = img.naturalHeight || img.height;
        const k = (Math.min(w, h) * this.opts.glyph.scale) / Math.max(iw, ih);
        this.lctx.drawImage(img, (w - iw * k) / 2, (h - ih * k) / 2, iw * k, ih * k);
        const data = this.lctx.getImageData(0, 0, w, h).data;
        this.lctx.clearRect(0, 0, w, h);
        this.lctx.font = this.font();
        this.lctx.textBaseline = 'top';

        const mask = new Uint8Array(this.cols * this.rows);
        const c = this.cell;
        for (let r = 0; r < this.rows; r++) {
            for (let col = 0; col < this.cols; col++) {
                const x = Math.min(w - 1, col * c + (c >> 1));
                const y = Math.min(h - 1, r * c + (c >> 1));
                if (data[(y * w + x) * 4 + 3] <= MASK_ALPHA) continue;
                const idx = r * this.cols + col;
                mask[idx] = 1;
                this.paintCell(idx);
                const lane = this.lanes[this.horizontal ? r : col];
                if (!lane) continue;
                const s = signed(this.horizontal ? col : r, lane.sign, this.span);
                if (lane.first < 0 || s < lane.first) lane.first = s;
                if (s > lane.last) lane.last = s;
            }
        }
        this.mask = mask;
    }

    font() {
        return `${Math.round(this.cell * 0.85)}px ${this.opts.fontFamily}`;
    }

    paintCell(idx) {
        const col = idx % this.cols;
        const row = (idx / this.cols) | 0;
        const x = col * this.cell;
        const y = row * this.cell;
        this.lctx.clearRect(x, y, this.cell, this.cell);
        this.lctx.fillStyle = Math.random() < 0.15 ? this.hot : this.dim;
        this.lctx.fillText(this.chars[idx], x, y);
    }

    // --- drops ------------------------------------------------------------

    newDrop(at) {
        const a = this.opts.animation;
        return {
            units: clamp(jitter(a.length.value, a.length.random), 0.01, 3),
            speed: Math.max(0.1, jitter(a.speed.value, a.speed.random)),
            travel: at,
        };
    }

    // A lane holds as many drops as fit: the next one leaves once the previous
    // has covered its gap, which is what keeps the rain from falling in waves.
    spawn(lane, at) {
        const g = this.opts.animation.gap;
        lane.drops.push(this.newDrop(at));
        lane.gap = clamp(jitter(g.value, g.random), 0.05, 5) * this.span;
    }

    start() {
        this.running = true;
        this.started = true;
        this.idle = false;
        if (!this.raf) this.raf = requestAnimationFrame(this.frame);
        this.lanes.forEach((l) => {
            l.head = -1;
            l.tail = -1;
        });
    }

    // Stops spawning. Lanes covering the glyph get one last drop that wipes it
    // away as it goes, spread out so the erase does not come down in a line.
    stop() {
        if (!this.running) return;
        this.running = false;
        this.lanes.forEach((l) => {
            if (l.first < 0) {
                // nothing to erase here, drops still off-screen just never come
                l.drops = l.drops.filter((d) => d.travel > 0);
                return;
            }
            const at = l.first - 2 - Math.random() * this.span * 0.3;
            if (!l.drops.some((d) => d.travel <= at)) l.drops.push(this.newDrop(at));
        });
    }

    destroy() {
        cancelAnimationFrame(this.raf);
        this.observer.disconnect();
        if (this.owned) this.canvas.remove();
    }

    // --- loop -------------------------------------------------------------

    frame(time) {
        this.raf = requestAnimationFrame(this.frame);
        const elapsed = time - this.last;
        if (elapsed < 1000 / this.opts.fps) return;
        const dt = Math.min(0.1, elapsed / 1000) || 0;
        this.last = time;

        for (let i = 0; i < this.churnAt.length; i++) {
            if (time < this.churnAt[i]) continue;
            this.churnAt[i] = time + 1000 / this.churnRate[i];
            this.chars[i] = this.randChar();
            if (this.mask && this.mask[i]) this.paintCell(i);
        }

        let alive = false;
        for (const lane of this.lanes) {
            const drops = lane.drops;
            if (this.running) {
                const last = drops[drops.length - 1];
                if (!last) this.spawn(lane, -Math.random() * this.span);
                else if (last.travel >= lane.gap) this.spawn(lane, 0);
            }
            // the glyph is erased behind the rearmost drop, not the leading one
            let rear = Infinity;
            for (let k = drops.length - 1; k >= 0; k--) {
                const d = drops[k];
                d.travel += d.speed * dt;
                const s = Math.round(d.travel);
                if (s - d.units * this.span > this.span) {
                    drops.splice(k, 1);
                    continue;
                }
                if (s > lane.head) lane.head = s;
                if (s < rear) rear = s;
            }
            if (!this.running && rear > lane.tail) lane.tail = rear;
            if (drops.length) alive = true;
        }

        this.draw();

        // Nothing left to animate: park the loop until the next start().
        if (!this.running && !alive) {
            cancelAnimationFrame(this.raf);
            this.raf = 0;
            if (this.started && !this.idle) {
                this.idle = true;
                this.opts.onIdle?.();
            }
        }
    }

    draw() {
        const o = this.opts;
        const fx =
            o.blur > 0 ||
            o.chromaticAberration > 0 ||
            o.filmGrain > 0 ||
            (o.bloom.intensity > 0 && o.bloom.radius > 0) ||
            o.hdrBloom.intensity > 0;
        const ctx = fx ? this.sctx : this.ctx;
        const w = this.canvas.width;
        const h = this.canvas.height;
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, w, h);
        ctx.font = this.font();
        ctx.textBaseline = 'top';

        // Revealed slice of the glyph, blitted from the pre-rendered layer.
        ctx.globalAlpha = o.color.glyphOpacity;
        for (const lane of this.lanes) {
            if (lane.first < 0) continue;
            const from = Math.max(lane.first, lane.tail + 1);
            const to = Math.min(lane.last, lane.head);
            if (to < from) continue;
            const a = signed(from, lane.sign, this.span);
            const b = signed(to, lane.sign, this.span);
            const r = this.cellRect(lane.i, Math.min(a, b), Math.max(a, b));
            ctx.drawImage(this.layer, ...r, ...r);
        }

        const c = this.cell;
        for (const lane of this.lanes) {
            for (const d of lane.drops) {
                const len = Math.max(1, Math.round(d.units * this.span));
                const head = Math.round(d.travel);
                for (let i = 0; i < len; i++) {
                    const s = head - i;
                    if (s < 0 || s >= this.span) continue;
                    const pos = signed(s, lane.sign, this.span);
                    const idx = this.index(lane.i, pos);
                    const onGlyph = this.mask && this.mask[idx];
                    ctx.globalAlpha =
                        (1 - i / len) *
                        (onGlyph ? o.color.glyphOpacity : o.color.rainOpacity);
                    ctx.fillStyle = onGlyph
                        ? this.hot
                        : this.ramp[Math.min(RAMP - 1, (i / len) * RAMP * 3) | 0];
                    const [x, y] = this.horizontal
                        ? [pos * c, lane.i * c]
                        : [lane.i * c, pos * c];
                    ctx.fillText(this.chars[idx], x, y);
                }
            }
        }
        ctx.globalAlpha = 1;

        if (fx) this.post(this.ctx, this.scene, o);
    }
}
