// Post-processing chain, plain 2D canvas: no WebGL, no shaders, no deps.
// Everything here is an approximation of the real thing; good enough on top of
// glyphs, and every effect is off by default so you only pay for what you use.

const NOISE_SIZE = 256;

export default function createPost() {
    const pool = [];
    let noise = null;

    // Scratch canvases are reused across frames, one per slot.
    const buf = (slot, w, h) => {
        const c = pool[slot] || (pool[slot] = document.createElement('canvas'));
        const ctx = c.getContext('2d');
        if (c.width !== w || c.height !== h) {
            c.width = w;
            c.height = h;
        } else {
            ctx.clearRect(0, 0, w, h);
        }
        ctx.globalAlpha = 1;
        ctx.globalCompositeOperation = 'source-over';
        ctx.filter = 'none';
        return c;
    };

    // Keeps only pixels brighter than `t`, at `scale` of the source size.
    // Real per-pixel pass instead of a brightness/contrast fudge; it runs on the
    // downscaled buffer so it stays cheap.
    const threshold = (slot, scene, w, h, t) => {
        const c = buf(slot, w, h);
        const ctx = c.getContext('2d');
        ctx.drawImage(scene, 0, 0, w, h);
        if (t <= 0) return c;
        const img = ctx.getImageData(0, 0, w, h);
        const d = img.data;
        const cut = t * 255;
        for (let i = 0; i < d.length; i += 4) {
            const a = d[i + 3] / 255;
            const lum =
                (0.2126 * d[i] + 0.7152 * d[i + 1] + 0.0722 * d[i + 2]) * a;
            if (lum < cut) d[i + 3] = 0;
        }
        ctx.putImageData(img, 0, 0);
        return c;
    };

    const add = (octx, src, w, h, intensity) => {
        octx.globalCompositeOperation = 'lighter';
        // intensity > 1 means stacking passes; cheaper than an HDR buffer
        let left = intensity;
        while (left > 0) {
            octx.globalAlpha = Math.min(1, left);
            octx.drawImage(src, 0, 0, w, h);
            left -= 1;
        }
        octx.globalAlpha = 1;
        octx.globalCompositeOperation = 'source-over';
    };

    const bloom = (octx, scene, w, h, o) => {
        const half = [Math.max(1, w >> 1), Math.max(1, h >> 1)];
        const bright = threshold(3, scene, half[0], half[1], o.threshold);
        const blurred = buf(4, half[0], half[1]);
        const bctx = blurred.getContext('2d');
        bctx.filter = `blur(${o.radius / 2}px)`;
        bctx.drawImage(bright, 0, 0);
        bctx.filter = 'none';
        add(octx, blurred, w, h, o.intensity);
    };

    // Mip chain down then back up, blending each level into the one above with
    // `scatter` as the mix. Same shape as the usual dual-filter HDR bloom, just
    // done with drawImage instead of framebuffers.
    const hdrBloom = (octx, scene, w, h, o) => {
        const mips = [
            threshold(
                5,
                scene,
                Math.max(1, w >> 1),
                Math.max(1, h >> 1),
                o.threshold
            ),
        ];
        for (let i = 1; i <= o.iterations; i++) {
            const mw = Math.max(1, w >> (i + 1));
            const mh = Math.max(1, h >> (i + 1));
            if (mw < 2 || mh < 2) break;
            const c = buf(5 + i, mw, mh);
            const ctx = c.getContext('2d');
            ctx.filter = 'blur(1px)';
            ctx.drawImage(mips[mips.length - 1], 0, 0, mw, mh);
            ctx.filter = 'none';
            mips.push(c);
        }
        for (let i = mips.length - 2; i >= 0; i--) {
            const ctx = mips[i].getContext('2d');
            ctx.globalAlpha = o.scatter;
            ctx.filter = 'blur(1px)';
            ctx.drawImage(mips[i + 1], 0, 0, mips[i].width, mips[i].height);
            ctx.filter = 'none';
            ctx.globalAlpha = 1;
        }
        add(octx, mips[0], w, h, o.intensity);
    };

    const makeNoise = () => {
        const c = document.createElement('canvas');
        c.width = c.height = NOISE_SIZE;
        const ctx = c.getContext('2d');
        const img = ctx.createImageData(NOISE_SIZE, NOISE_SIZE);
        const d = img.data;
        for (let i = 0; i < d.length; i += 4) {
            const v = (Math.random() * 255) | 0;
            d[i] = d[i + 1] = d[i + 2] = v;
            d[i + 3] = 255;
        }
        ctx.putImageData(img, 0, 0);
        return c;
    };

    // Overlay-blended noise, then clipped back to what the frame already had so
    // the canvas stays transparent where nothing was drawn.
    const grain = (octx, w, h, amount) => {
        if (!noise) noise = makeNoise();
        const out = octx.canvas;
        const c = buf(2, w, h);
        const ctx = c.getContext('2d');
        ctx.drawImage(out, 0, 0);
        ctx.globalCompositeOperation = 'overlay';
        ctx.globalAlpha = amount;
        ctx.fillStyle = ctx.createPattern(noise, 'repeat');
        ctx.translate(-((Math.random() * NOISE_SIZE) | 0), -((Math.random() * NOISE_SIZE) | 0));
        ctx.fillRect(0, 0, w + NOISE_SIZE, h + NOISE_SIZE);
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.globalAlpha = 1;
        ctx.globalCompositeOperation = 'destination-in';
        ctx.drawImage(out, 0, 0);
        octx.globalCompositeOperation = 'copy';
        octx.drawImage(c, 0, 0);
        octx.globalCompositeOperation = 'source-over';
    };

    // One channel of the scene, tinted and shifted sideways.
    const channel = (slot, scene, w, h, tint, dx) => {
        const c = buf(slot, w, h);
        const ctx = c.getContext('2d');
        ctx.drawImage(scene, dx, 0);
        ctx.globalCompositeOperation = 'multiply';
        ctx.fillStyle = tint;
        ctx.fillRect(0, 0, w, h);
        // multiply paints the tint over empty pixels too, so alpha is restored
        ctx.globalCompositeOperation = 'destination-in';
        ctx.drawImage(scene, dx, 0);
        return c;
    };

    const aberrate = (octx, scene, w, h, px) => {
        octx.globalCompositeOperation = 'lighter';
        octx.drawImage(channel(0, scene, w, h, '#ff0000', -px), 0, 0);
        octx.drawImage(channel(1, scene, w, h, '#00ff00', 0), 0, 0);
        octx.drawImage(channel(2, scene, w, h, '#0000ff', px), 0, 0);
        octx.globalCompositeOperation = 'source-over';
    };

    return function post(octx, scene, o) {
        const w = scene.width;
        const h = scene.height;
        octx.setTransform(1, 0, 0, 1, 0, 0);
        octx.globalAlpha = 1;
        octx.globalCompositeOperation = 'source-over';
        octx.clearRect(0, 0, w, h);

        octx.filter = o.blur > 0 ? `blur(${o.blur}px)` : 'none';
        if (o.chromaticAberration > 0) {
            aberrate(octx, scene, w, h, o.chromaticAberration);
        } else {
            octx.drawImage(scene, 0, 0);
        }
        octx.filter = 'none';

        if (o.bloom.intensity > 0 && o.bloom.radius > 0) {
            bloom(octx, scene, w, h, o.bloom);
        }
        if (o.hdrBloom.intensity > 0) hdrBloom(octx, scene, w, h, o.hdrBloom);
        if (o.filmGrain > 0) grain(octx, w, h, o.filmGrain);

        octx.globalAlpha = 1;
        octx.globalCompositeOperation = 'source-over';
    };
}
